-- The ZIP centers a zone is filled from.
--
-- Data for reference.zip_centroids (created by 20261001120000_a-zone-you-drew-
-- named-no-zips.sql, which explains why it exists and why it is not in
-- `public`).
--
-- Source: U.S. Census Bureau, 2025 Gazetteer Files, ZIP Code Tabulation Areas,
-- national file (2025_Gaz_zcta_national.txt, sha256
-- 100e70311af1655406d939a930f183559c902b57e1f20e714b43ef4776f6ac3d), from
-- https://www2.census.gov/geo/docs/maps-data/data/gazetteer/2025_Gazetteer/
-- A work of the U.S. Government: public domain.
--
-- One line per ZCTA: zip, INTPTLAT, INTPTLONG (4 decimals, about 11 m), and
-- round(sqrt(ALAND / pi)) in metres. Generated with:
--
--   tail -n +2 2025_Gaz_zcta_national.txt | tr -d '\r' | awk -F'|' \
--     '{gsub(/ /,"",$8); printf "%s,%.4f,%.4f,%d\n",$1,$7,$8,int(sqrt($3/3.14159265)+0.5)}'
--
-- ── APPLYING THIS TO PRODUCTION ──────────────────────────────────────────
--
-- This file is ~950 KB, about twenty times the next largest migration. Do NOT
-- apply it through the Supabase MCP's apply_migration: that means retyping
-- 33,791 rows of coordinates as a tool argument. Run it from disk instead
-- (`supabase db push`, or psql -f against the connection string and then
-- record it in supabase_migrations.schema_migrations), after the schema file.
--
-- Idempotent: re-running it updates a changed row and inserts a missing one.
-- It never deletes, so a later vintage of the file can be loaded on top.

DO $pre$
BEGIN
  IF to_regclass('reference.zip_centroids') IS NULL THEN
    RAISE EXCEPTION 'reference.zip_centroids does not exist; apply 20261001120000 first';
  END IF;
END
$pre$;

