$zcta$, E'\n'), E'\n') AS l
 WHERE l <> ''
ON CONFLICT (zip) DO UPDATE
   SET lat = EXCLUDED.lat, lng = EXCLUDED.lng, radius_m = EXCLUDED.radius_m
 WHERE (z.lat, z.lng, z.radius_m) IS DISTINCT FROM (EXCLUDED.lat, EXCLUDED.lng, EXCLUDED.radius_m);

-- What this file establishes: every row it carries is present. Checked by
-- count and by three ZIPs whose places nobody will dispute.
DO $check$
DECLARE _n integer; _lat double precision; _lng double precision;
BEGIN
  SELECT count(*) INTO _n FROM reference.zip_centroids;
  IF _n < 33791 THEN
    RAISE EXCEPTION 'reference.zip_centroids holds % rows; this file loads 33791', _n;
  END IF;
  SELECT c.lat, c.lng INTO _lat, _lng FROM reference.zip_centroids c WHERE c.zip = '78701';
  IF _lat IS NULL OR abs(_lat - 30.27) > 0.05 OR abs(_lng + 97.74) > 0.05 THEN
    RAISE EXCEPTION '78701 is not in downtown Austin (%, %)', _lat, _lng;
  END IF;
  SELECT c.lat, c.lng INTO _lat, _lng FROM reference.zip_centroids c WHERE c.zip = '01810';
  IF _lat IS NULL OR abs(_lat - 42.65) > 0.1 OR abs(_lng + 71.16) > 0.1 THEN
    RAISE EXCEPTION '01810 (Andover, MA) lost its leading zero or its place (%, %)', _lat, _lng;
  END IF;
  SELECT c.lat, c.lng INTO _lat, _lng FROM reference.zip_centroids c WHERE c.zip = '99501';
  IF _lat IS NULL OR abs(_lat - 61.22) > 0.05 OR abs(_lng + 149.86) > 0.05 THEN
    RAISE EXCEPTION '99501 is not in Anchorage (%, %)', _lat, _lng;
  END IF;
  RAISE NOTICE 'reference.zip_centroids: % ZIP centers', _n;
END
$check$;
